#!/usr/bin/env bash
# The frozen project at format 0 (RFC-032): made by 0.7.2's own code, from its tag, as a 0.7.2 user made it — the
# tutorial kit's tickets, a dataset and its gold reference, two offline runs (the bundled echo provider) and a promoted
# baseline. tests/test_format.py migrates a copy of it to this release's format on every CI run.
#
#   bash tests/fixtures/formats/make_format_0.sh     (from harness/; rewrites tests/fixtures/formats/0/)
#
# Run once, when the fixture is made; the result is committed and never regenerated by a later release.
set -euo pipefail
here="$(cd "$(dirname "$0")" && pwd)"
harness="$(cd "$here/../../.." && pwd)"
py="${PYTHON:-$harness/.venv/bin/python}"
work="$(mktemp -d "${TMPDIR:-/tmp}/evh-format0-XXXXXX")"
trap 'rm -rf "$work"' EXIT
git -C "$harness/.." archive v0.7.2 harness | tar -x -C "$work"
evh() { EVAL_HOME="$work/p" EVAL_STORE=files EVAL_BUILD_REF=format-0-fixture "$py" "$work/harness/scripts/cli.py" "$@"; }
mkdir -p "$work/p"
cd "$work/p"
evh init --tutorial >/dev/null
cp -r tutorial/tickets data/sources/tickets
cp tutorial/configs/tickets_lead1.yaml tutorial/configs/tickets_lead2.yaml data/configs/
evh dataset-create --dataset-id tickets_v1 --source-dir data/sources/tickets --glob "*.txt" >/dev/null
evh dataset-materialize --dataset-id tickets_v1 >/dev/null
evh label-import tutorial/gold --dataset-id tickets_v1 --set kit_gold --by me >/dev/null
evh reference-promote --dataset-id tickets_v1 --labels kit_gold --tier gold --by me \
  --reason "the kit's own references" >/dev/null
evh run --config data/configs/tickets_lead1.yaml >/dev/null
evh run --config data/configs/tickets_lead2.yaml >/dev/null
runs=(data/runs/tickets_lead2*)
run="$(basename "${runs[0]}")"
evh run-promote --run "$run" --reason "lead2 covers more of the reference than lead1 on the kit's tickets" >/dev/null
evh leaderboard --dataset-id tickets_v1 --json > "$work/leaderboard.json"
rm -rf "$here/0"
mkdir -p "$here/0"
cp -r data "$here/0/data"
rm -rf "$here/0/data/materialized"   # derived, gitignored in a project; materialize makes it again
# 0.7.2's own leaderboard of this data: the views a migration must keep (RFC-032)
cp "$work/leaderboard.json" "$here/0/leaderboard-0.7.2.json"
echo "made $here/0: $(find "$here/0" -type f | wc -l) files"
